#!/usr/bin/env python3
"""The skill table's tool (plan.md 4.5.2.2): the candidates, the generated files, the table's own consistency.

    python contracts/tools/skills.py                      # write the generated files
    python contracts/tools/skills.py --check              # exit 1 if anything is wrong; changes nothing
    python contracts/tools/skills.py candidates --agent microscope_agent --observable O --configuration C

Three things, and each is read by more than one place, which is why they are
here and not in an agent:

1. `candidates()`: what a question must answer for. Every landed skill
   whose applies_to matches, plus every legacy inequality of that agent.
   Code decides this list. The model decides, for each candidate, used or
   not applied, with a reason; a candidate marked safety and a decision the
   person fixed are not the model's. The dispatcher uses it, and the commit
   gate derives it again to judge a run sheet.
2. The generated files: one page per skill under
   `<agent>/.claude/skill-docs/`, and ONE Claude Code skill per agent,
   `<agent>/.claude/skills/run-skills/SKILL.md`, which tells a session to
   call the dispatcher. Pages are outside `.claude/skills/` on purpose:
   Claude Code loads every skill's name and description at session start,
   and a session needs one trigger, not one per calculation.
3. `problems()`: whether the table agrees with itself, with the registries,
   with the files it names and with the pinned store entries. Check 99 calls
   it at every commit.

Standard library only, and nothing newer than Python 3.9, so bare `python`
runs it on every computer here.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import re
import sys
from pathlib import Path

REPO = Path(__file__).resolve().parents[2]
AGENTS = ("microscope_agent", "simulation_agent")
HEADER = ("<!-- Generated by contracts/tools/skills.py from contracts/skills.json. "
          "Edit the table and run the tool again; an edit made here is overwritten. -->")
DISPATCHER = "src/run_skills.py"


def load(root: Path = REPO) -> dict:
    return json.loads((root / "contracts" / "skills.json").read_text(encoding="utf-8"))


def ref(m: dict) -> str:
    return f"{m['id']}@v{m['version']}"


def matches(m: dict, observable: str, configuration: str) -> bool:
    a = m["applies_to"]
    return observable in a["observables"] and configuration in a["configurations"]


def candidates(table: dict, agent: str, observable: str, configuration: str) -> dict:
    """The candidates a question must answer for, and what binds the answer.

    Code decides applicability: every landed skill whose applies_to matches,
    and every legacy inequality of the agent, is a candidate. The model then
    decides, for every candidate, used or not applied, with a reason. Two
    things bind it. A candidate marked `safety` is always used, because a
    model makes no safety decision. A decision in the row's `fixed` is the
    person's. A suggestion binds nobody.
    """
    mine = lambda m: m["entry"]["script"].startswith(agent + "/")
    row = next((r for r in table["rows"]
                if r["observable"] == observable and configuration in r["configurations"]), None)
    skills = [m for m in table["skills"] if mine(m) and matches(m, observable, configuration)]
    legacy = [q for q in table["legacy_inequalities"] if q["agent"] == agent]
    refs = [ref(m) for m in skills] + [f"legacy:{q['id']}" for q in legacy]
    safety = [ref(m) for m in skills if m.get("safety")] + [f"legacy:{q['id']}" for q in legacy if q.get("safety")]
    fixed = [f for f in (row or {}).get("fixed", []) if f["ref"] in refs and f["ref"] not in safety]
    bound = set(safety) | {f["ref"] for f in fixed}
    planned = [{"ref": ref(m), "parameter": m.get("parameter", ""), "side": m.get("side", "value")}
               for m in table["planned"] if mine(m) and matches(m, observable, configuration)]
    return {
        "covered": bool(row or skills or planned),
        "candidates": refs,
        "decided_by_code": [{"ref": r, "verdict": "used",
                             "why": "It rests on the safety policy, so it is always used and no model decides it."}
                            for r in safety],
        "decided_by_person": [{"ref": f["ref"], "verdict": f["verdict"],
                               "why": f"The person fixed it: \"{f['persons_words']}\" ({f['ideas']})."} for f in fixed],
        "for_the_model": [r for r in refs if r not in bound],
        "suggestions": [s for s in (row or {}).get("suggestions", []) if s["ref"] in refs and s["ref"] not in bound],
        "planned_missing": planned,
    }


def agent_of(m: dict) -> str:
    return m["entry"]["script"].split("/", 1)[0]


def doc_path(m: dict) -> str:
    return f"{agent_of(m)}/.claude/skill-docs/{m['id']}_v{m['version']}.md"


def render_doc(m: dict, landed: bool) -> str:
    lines = [HEADER, "", f"# {ref(m)}", "", m["summary"], "",
             f"- **Kind:** `{m['kind']}`, side effect `{m['side_effect']}`."]
    if "parameter" in m:
        lines.append(f"- **Bounds:** `{m['parameter']}`, side `{m['side']}`.")
    a = m["applies_to"]
    lines += [f"- **Applies to:** observables {', '.join('`' + o + '`' for o in a['observables'])} on "
              f"{', '.join('`' + c + '`' for c in a['configurations'])}.",
              f"- **State:** {'landed' if landed else 'planned: its code and a running case have not landed, so no run can use it'}.",
              "", "## Inputs", "", "| input | unit | obtained by | what it is |", "|---|---|---|---|"]
    for i in m["inputs"]:
        how = i["obtained_by"] + (", a judgement" if i.get("judgement") else "")
        lines.append(f"| `{i['name']}` | {i['unit']} | {how} | {i['meaning']} |")
    lines += ["", "A missing input refuses the run before any code runs, and the run sheet says how the input "
              "is obtained. Never fill one with an estimate of your own.", "", "## Outputs", ""]
    lines += [f"- `{o['name']}` ({o['unit']}): {o['meaning']}" for o in m["outputs"]]
    s = m["source"]
    lines += ["", "## Source", "", f"{s['citation']}." + (f" {s['locus'][:1].upper() + s['locus'][1:]}." if s.get("locus") else "")]
    if s.get("entry"):
        pin = f"pinned at sha256 `{s['sha256'][:12]}`" if s.get("sha256") else "not pinned yet, because the entry is not in the store"
        lines += ["", f"Store entry `{s['entry']}`, {pin}."]
    if m.get("validity"):
        lines += ["", f"**Where it holds.** {m['validity'][:1].upper() + m['validity'][1:]}."]
    if m.get("uses_skills"):
        lines += ["", "**Uses.** " + ", ".join("`" + u + "`" for u in m["uses_skills"]) + "."]
    if m.get("note"):
        lines += ["", m["note"]]
    lines += ["", "## Code and cases", "", f"- `{m['entry']['script']}`, function `{m['entry']['function']}`",
              f"- `{m['cases']}`", "",
              "Run it only through the dispatcher. Do not run the script, and do not compute its result by hand: "
              "a value a model works out cannot enter a card.", ""]
    return "\n".join(lines)


def render_skill(table: dict, agent: str) -> str:
    n_skill = sum(agent_of(m) == agent for m in table["skills"])
    n_plan = sum(agent_of(m) == agent for m in table["planned"])
    n_leg = sum(q["agent"] == agent for q in table["legacy_inequalities"])
    description = ("Get the bounds and computed values a question needs. Use in S3, for any question, instead of "
                   "computing anything yourself: you choose which candidates apply, with a reason for each, and the "
                   "dispatcher runs them and writes the run sheet.")
    return "\n".join([
        "---", "name: run-skills", f"description: {json.dumps(description, ensure_ascii=False)}", "---", "", HEADER, "",
        "# Run the skills a question needs", "",
        f"`contracts/skills.json` declares {n_skill} landed skills, {n_plan} planned and {n_leg} legacy inequalities "
        "for this agent. You choose which candidates apply to the question, and you say why for each one. You "
        "never compute what they compute.", "",
        "## What to do", "",
        f"1. Ask the dispatcher, `{DISPATCHER}`, for the question's candidates. Code decides the list: every "
        "landed skill whose declaration matches the observable and configuration, and every legacy inequality.",
        "2. **Answer for every candidate**: `used` or `not_applied`, with your reason in a sentence a person can "
        "check. The table's suggestions show what the design session proposed and why; adopt one or overrule "
        "it, in your own words either way. Leaving a candidate unanswered fails the run.",
        "3. Hand your answers to the dispatcher. It runs every candidate you marked `used`, and writes the run "
        "sheet into the question's folder.",
        "4. Read the run sheet. Each value carries the skill that computed it, the inputs it used and its grade.",
        "5. A run that was **refused** lists `requires`: each missing input and how it is obtained, by a "
        "measurement, from the person, from a source, or from another skill. That is what has to happen before "
        "the bound exists. Do not supply the input yourself. `incomplete_because` names each bound you chose "
        "that did not come back: an interval missing that side is incomplete, not unconstrained.",
        "6. `planned_missing` lists bounds that are designed and not built. Say so in the plan.", "",
        "## What binds your choice", "",
        "- **A candidate marked safety is always used.** The dispatcher decides it. You do not.",
        "- **A decision the person fixed is the person's.** You do not overrule it.",
        "- **A reason is required for both verdicts.** \"Not relevant\" is not a reason; say what about this "
        "question makes it so.",
        "- **You may not type a value** into the run sheet or a card. Values are the code's.", "",
        "## Where to read about one skill", "",
        "`.claude/skill-docs/<id>_v<N>.md`, one page per skill: its inputs and how each is obtained, its "
        "outputs, its source, and its code. Those pages are reference. They are not instructions to run anything.", "",
        "## What this does not touch", "",
        "Whether a run may start is not decided here. The checks of the person's approval, the safety limits, "
        "the Micro-Manager configuration and the run lock stay in the runtime's code and run every time.", ""])


def generated(table: dict) -> dict[str, str]:
    out: dict[str, str] = {}
    for m in table["skills"]:
        out[doc_path(m)] = render_doc(m, True)
    for m in table["planned"]:
        out[doc_path(m)] = render_doc(m, False)
    for agent in AGENTS:
        if any(agent_of(m) == agent for m in table["skills"] + table["planned"]) or \
                any(q["agent"] == agent for q in table["legacy_inequalities"]):
            out[f"{agent}/.claude/skills/run-skills/SKILL.md"] = render_skill(table, agent)
    return out


def _sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes().replace(b"\r\n", b"\n")).hexdigest()


def problems(root: Path = REPO) -> list[tuple[str, str]]:
    """Everything wrong with the table and what it names, as (message, path). Reads; changes nothing."""
    out: list[tuple[str, str]] = []
    rel = "contracts/skills.json"
    try:
        table = load(root)
    except (OSError, json.JSONDecodeError) as exc:
        return [(f"cannot read the skill table: {exc}", rel)]
    try:
        observables = {o["id"] for o in json.loads((root / "contracts/observables.json").read_text(encoding="utf-8"))["observables"]}
        units = json.loads((root / "contracts/units.json").read_text(encoding="utf-8"))
        symbols = set(units.get("units", {})) if isinstance(units, dict) else set()
        configs = set()
        for cap in sorted((root / "contracts/capabilities").glob("*.json")):
            data = json.loads(cap.read_text(encoding="utf-8"))
            configs |= {c.get("config") for c in data.get("configurations", [])}
    except (OSError, json.JSONDecodeError, KeyError) as exc:
        return [(f"cannot read a registry the skill table is judged against: {exc}", rel)]

    every = table["skills"] + table["planned"]
    refs = [ref(m) for m in every]
    for r in sorted({r for r in refs if refs.count(r) > 1}):
        out.append((f"{r} is declared more than once across skills[] and planned[]", rel))
    legacy_ids = [q["id"] for q in table["legacy_inequalities"]]
    for i in sorted({i for i in legacy_ids if legacy_ids.count(i) > 1}):
        out.append((f"legacy inequality {i!r} is listed more than once", rel))
    for m in every:
        r = ref(m)
        stem = f"{m['id']}_v{m['version']}"
        if Path(m["entry"]["script"]).name != stem + ".py" or Path(m["cases"]).name != stem + ".cases.json":
            out.append((f"{r}: its script and cases must be {stem}.py and {stem}.cases.json", rel))
        if agent_of(m) != m["cases"].split("/", 1)[0]:
            out.append((f"{r}: its script and its cases are in different agents", rel))
        for o in m["applies_to"]["observables"]:
            if o not in observables:
                out.append((f"{r} applies to observable {o!r}, which contracts/observables.json does not define", rel))
        for c in m["applies_to"]["configurations"]:
            if c not in configs:
                out.append((f"{r} applies to configuration {c!r}, which no file in contracts/capabilities/ declares", rel))
        for io in m["inputs"] + m["outputs"]:
            if symbols and io["unit"] not in symbols:
                out.append((f"{r}: {io['name']} is in {io['unit']!r}, which contracts/units.json does not define", rel))
        for u in m.get("uses_skills", []):
            if u not in refs:
                out.append((f"{r} uses {u}, which the table does not declare", rel))
    for m in table["skills"]:
        r = ref(m)
        if not (root / agent_of(m)).is_dir():
            continue
        for label, p in (("script", m["entry"]["script"]), ("cases", m["cases"])):
            if not (root / p).is_file():
                out.append((f"{r} is in skills[], so it has landed, and its {label} is not in the tree", p))
        cases = root / m["cases"]
        if cases.is_file():
            try:
                data = json.loads(cases.read_text(encoding="utf-8"))
                if not isinstance(data, list) or not any(isinstance(c, dict) and not c.get("not_run") for c in data):
                    out.append((f"{r} has no case that runs: a skill lands only with one", m["cases"]))
            except json.JSONDecodeError as exc:
                out.append((f"{r}: its cases file is not JSON: {exc}", m["cases"]))
        s = m["source"]
        if s.get("entry") and not s.get("sha256"):
            out.append((f"{r} has landed and its source entry {s['entry']!r} is not pinned by sha256", rel))
    for m in every:
        s = m["source"]
        if s.get("entry") and s.get("sha256"):
            entry = root / "librarian_agent" / "kb" / "entries" / f"{s['entry']}.json"
            if not entry.is_file():
                if (root / "librarian_agent").is_dir():
                    out.append((f"{ref(m)} pins store entry {s['entry']!r}, which the store does not hold", rel))
            elif _sha(entry) != s["sha256"]:
                out.append((f"{ref(m)} pins store entry {s['entry']!r} at {s['sha256'][:12]}, and the entry in the "
                            f"tree hashes to {_sha(entry)[:12]}: the source changed after the skill landed, so the "
                            "skill is re-read against it and lands as a new version if its formula moved", rel))
    known = {q["id"] for q in table["legacy_inequalities"]}
    seen_rows = set()
    for row in table["rows"]:
        where = f"the row for {row['observable']!r}"
        if row["observable"] not in observables:
            out.append((f"{where} names an observable contracts/observables.json does not define", rel))
        for c in row["configurations"]:
            if c not in configs:
                out.append((f"{where} names configuration {c!r}, which no capabilities file declares", rel))
            if (row["observable"], c) in seen_rows:
                out.append((f"{row['observable']!r} on {c!r} has two rows", rel))
            seen_rows.add((row["observable"], c))
        named = set(refs) | {f"legacy:{i}" for i in known}
        safe = {f"legacy:{q['id']}" for q in table["legacy_inequalities"] if q.get("safety")} | \
               {ref(m) for m in every if m.get("safety")}
        for label in ("fixed", "suggestions"):
            seen = []
            for item in row[label]:
                if item["ref"] not in named:
                    out.append((f"{where} has a {label} entry for {item['ref']!r}, which the table does not declare", rel))
                if item["ref"] in safe:
                    out.append((f"{where} has a {label} entry for {item['ref']!r}, which is marked safety: it is "
                                "always used, and neither a suggestion nor a fixed decision may say otherwise", rel))
                if item["ref"] in seen:
                    out.append((f"{where} has two {label} entries for {item['ref']!r}", rel))
                seen.append(item["ref"])

    declared_files = {m["entry"]["script"] for m in every} | {m["cases"] for m in every}
    for agent in AGENTS:
        folder = root / agent / "src" / "skills"
        if folder.is_dir():
            for p in sorted(folder.iterdir()):
                relp = p.relative_to(root).as_posix()
                if p.is_file() and relp not in declared_files and not p.name.startswith("__"):
                    out.append(("a file under src/skills/ that no manifest in the table names: every skill file "
                                "has one manifest, and every manifest its two files", relp))

    for relp, text in sorted(generated(table).items()):
        agent = relp.split("/", 1)[0]
        if not (root / agent).is_dir():
            continue
        p = root / relp
        if not p.is_file():
            out.append(("a generated file the table calls for is missing. Run python contracts/tools/skills.py", relp))
        elif p.read_text(encoding="utf-8").replace("\r\n", "\n") != text:
            out.append(("differs from what the table renders. It is generated: edit contracts/skills.json and run "
                        "python contracts/tools/skills.py", relp))
    wanted = set(generated(table))
    for agent in AGENTS:
        base = root / agent / ".claude"
        for p in sorted(list((base / "skill-docs").glob("*.md")) if (base / "skill-docs").is_dir() else []):
            if p.relative_to(root).as_posix() not in wanted:
                out.append(("a skill page for a skill the table does not declare", p.relative_to(root).as_posix()))
        for p in sorted((base / "skills").glob("calc-*/SKILL.md")) if (base / "skills").is_dir() else []:
            out.append(("a per-calculation Claude Code skill from before the dispatcher: one skill per agent "
                        "is the rule, so remove it", p.relative_to(root).as_posix()))
    return out


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    ap.add_argument("command", nargs="?", choices=["candidates"], help="print a question's candidates as JSON")
    ap.add_argument("--check", action="store_true", help="exit 1 if anything is wrong; changes nothing")
    ap.add_argument("--agent", choices=AGENTS)
    ap.add_argument("--observable")
    ap.add_argument("--configuration")
    args = ap.parse_args(argv)

    if args.command == "candidates":
        if not (args.agent and args.observable and args.configuration):
            ap.error("candidates needs --agent, --observable and --configuration")
        print(json.dumps(candidates(load(), args.agent, args.observable, args.configuration), ensure_ascii=False, indent=2))
        return 0

    if not args.check:
        table = load()
        files = generated(table)
        for relp, text in files.items():
            p = REPO / relp
            p.parent.mkdir(parents=True, exist_ok=True)
            with open(p, "w", encoding="utf-8", newline="\n") as fh:
                fh.write(text)
        print(f"skills: wrote {len(files)} generated files")
    found = problems()
    for message, where in found:
        print(f"  {message} [{where}]")
    print(f"skills: {len(found)} problems" if found else "skills: the table, its files and its generated pages agree")
    return 1 if found else 0


if __name__ == "__main__":
    sys.exit(main())
